import{_ as a,o,c as s,a2 as n}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Búsqueda de contenido","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/content-search.md","filePath":"es-ES/user-guide/content-search.md","lastUpdated":1788568709000}'),r={name:"es-ES/user-guide/content-search.md"};function i(d,e,c,t,l,u){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="busqueda-de-contenido" tabindex="-1">Búsqueda de contenido <a class="header-anchor" href="#busqueda-de-contenido" aria-label="Permalink to &quot;Búsqueda de contenido&quot;">​</a></h1><p>El plugin Búsqueda de contenido busca texto dentro de documentos locales y crea el índice en segundo plano. Funciona junto con la búsqueda normal de nombres de archivo de Lertaro.</p><h2 id="primeros-pasos" tabindex="-1">Primeros pasos <a class="header-anchor" href="#primeros-pasos" aria-label="Permalink to &quot;Primeros pasos&quot;">​</a></h2><p>Abre <strong>Configuración → Plugins → Búsqueda de contenido → Configurar</strong>, añade al menos una carpeta supervisada y guarda. La palabra clave activadora predeterminada es <code>cs</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cs plan del proyecto</span></span></code></pre></div><p>La palabra clave debe ir seguida de un espacio. Si <code>cs</code> entra en conflicto con tu flujo de trabajo, puedes cambiarla en la configuración del plugin.</p><h2 id="que-se-indexa" tabindex="-1">Qué se indexa <a class="header-anchor" href="#que-se-indexa" aria-label="Permalink to &quot;Qué se indexa&quot;">​</a></h2><ul><li><strong>Carpetas supervisadas</strong>: El plugin registra las carpetas locales configuradas en el servicio de índices del anfitrión. La detección inicial e incremental usa la enumeración de directorios indexados del SDK y notificaciones agrupadas de cambios de directorio; cada carpeta debe estar cubierta por un índice de unidad local o de carpeta del anfitrión, de lo contrario la enumeración no devuelve archivos. También admite variables de entorno como <code>%USERPROFILE%</code>.</li><li><strong>Extensiones</strong>: De forma predeterminada se incluyen <code>txt</code>, <code>md</code>, <code>pdf</code>, <code>docx</code>, <code>docm</code>, <code>pptx</code>, <code>pptm</code>, <code>xlsx</code>, <code>xlsm</code> y <code>csv</code>. Puedes modificar la lista separada por comas.</li><li><strong>Archivos PDF</strong>: Se busca tanto el texto extraíble de las páginas como los valores guardados de los campos de formularios PDF rellenables.</li><li><strong>Tamaño de archivo</strong>: Los archivos que superen el límite por archivo se omiten. El índice de contenido tiene además un límite independiente; <code>0</code> significa sin límite.</li><li><strong>Rutas excluidas</strong>: Añade expresiones regulares separadas por punto y coma para excluir rutas completas. Si coincide una carpeta, también se excluye su contenido.</li></ul><p>Solo se buscan los archivos cuyo texto se ha extraído correctamente. Los archivos binarios sin un extractor de documentos adecuado se omiten en lugar de indexarse como texto ilegible.</p><h2 id="como-buscar" tabindex="-1">Cómo buscar <a class="header-anchor" href="#como-buscar" aria-label="Permalink to &quot;Cómo buscar&quot;">​</a></h2><p>Escribe <code>cs</code>, un espacio y tus palabras clave en la ventana de búsqueda rápida. Los resultados muestran un fragmento de texto y la carpeta contenedora; pulsa <code>Enter</code> para abrir el archivo seleccionado. Cuando hay resultados y no se ha elegido un filtro de tipo, esos archivos también aparecen en la ventana de búsqueda completa.</p><p>Durante la creación inicial del índice, el marcador de posición <code>cs</code> muestra cuántos archivos están indexados y cuántas tareas quedan. Cuando el observador del anfitrión informa de directorios nuevos o modificados, el plugin procesa sus archivos en segundo plano, por lo que la búsqueda normal de nombres sigue disponible. Una vez estabilizado el índice, el plugin no vuelve a recorrer periódicamente el sistema de archivos.</p><h2 id="borrar-y-reconstruir" tabindex="-1">Borrar y reconstruir <a class="header-anchor" href="#borrar-y-reconstruir" aria-label="Permalink to &quot;Borrar y reconstruir&quot;">​</a></h2><p>La configuración de Búsqueda de contenido ofrece dos acciones distintas:</p><ul><li><strong>Borrar índice</strong> elimina el índice de contenido sin volver a analizar las carpetas supervisadas.</li><li><strong>Reconstruir índice</strong> elimina el índice de contenido y vuelve a analizar todas las carpetas supervisadas.</li></ul><p>Estas acciones solo afectan al índice de Búsqueda de contenido; no eliminan el índice normal de nombres de archivo de Lertaro.</p><h2 id="consejos" tabindex="-1">Consejos <a class="header-anchor" href="#consejos" aria-label="Permalink to &quot;Consejos&quot;">​</a></h2><ul><li>Si un archivo no aparece, revisa su carpeta, extensión, patrones excluidos y límite de tamaño.</li><li>Después de cambiar las carpetas o las reglas, guarda la configuración y espera a que termine el análisis en segundo plano.</li><li>Si quieres volver a extraer archivos existentes después de cambiar las reglas, usa <strong>Reconstruir índice</strong>.</li></ul>',18)])])}const h=a(r,[["render",i]]);export{m as __pageData,h as default};
